/** HIGHFLY P7 premium responsive bag and equipment. Game data only, no copied image. */
const CSS="\nbody.hf-p7 #hf-p5-overlay{background:#020415cc;backdrop-filter:blur(6px)}\nbody.hf-p7 #hf-p5-overlay .hf-p5-panel{width:min(1120px,97vw);height:min(670px,95vh);background:linear-gradient(130deg,#260f50,#0d1034 56%,#2d1252);border:2px solid #d680ff;border-radius:18px;box-shadow:0 0 0 2px #e8b06755,0 0 42px #af4dff77,inset 0 0 24px #a549d62d}\nbody.hf-p7 .hf-p5-tabs{background:#160d35;border-bottom:1px solid #e8b067;padding:5px 10px;gap:8px}\nbody.hf-p7 .hf-p5-tabs button{background:#251746;color:#efd5ff;border:1px solid #8944b3;border-radius:9px;font-size:11px;padding:7px 12px}\nbody.hf-p7 .hf-p5-tabs button.active{background:linear-gradient(90deg,#8d4d28,#592362);color:#ffefbc;border-color:#ffcd78;box-shadow:0 0 12px #ffac5380}\nbody.hf-p7 .hf-p5-body{gap:10px;padding:9px;min-height:0}\nbody.hf-p7 .hf-p5-list{display:flex;flex-direction:column;overflow-y:auto}\nbody.hf-p7 .hf-p5-detail{width:28%;min-width:155px;background:linear-gradient(150deg,#170e37,#2b164e);border:1px solid #a35fd9;border-radius:12px;overflow-y:auto}\nbody.hf-p7 .hf-p5-detail h3{color:#ffe4a5;font-size:15px}\nbody.hf-p7 .hf-p5-detail button{background:linear-gradient(100deg,#7c3790,#332779);color:#ffeecf;border:1px solid #e8aa65;margin-top:5px}\nbody.hf-p7 .p7-head{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #8e55ac;padding:4px 5px 9px;margin-bottom:8px;gap:10px}\nbody.hf-p7 .p7-title{font:bold clamp(17px,2.3vw,27px) Georgia,serif;color:#fff0d2;letter-spacing:1px;text-shadow:0 0 12px #c05cff}\nbody.hf-p7 .p7-facts{display:flex;gap:6px;font-size:10px;color:#ffe0a0}\nbody.hf-p7 .p7-facts span{padding:5px 8px;background:#29123f;border:1px solid #9c60bf;border-radius:8px}\nbody.hf-p7 .p7-filters{display:flex;gap:6px;overflow-x:auto;white-space:nowrap;padding-bottom:5px}\nbody.hf-p7 .p7-filter{background:#231546;border:1px solid #9559ba;color:#edd8fc;border-radius:10px;padding:7px 10px;font:bold 10px system-ui;flex-shrink:0}\nbody.hf-p7 .p7-filter.active{background:linear-gradient(110deg,#a96a2d,#582763);color:#fff;border-color:#f6ca79;box-shadow:0 0 10px #ec9b5b88}\nbody.hf-p7 .p7-searchline{display:flex;gap:7px;margin:6px 0 8px}\nbody.hf-p7 .p7-search{flex:1;min-width:0;color:#fff;background:#150d32;border:1px solid #b66feb;border-radius:9px;padding:8px;font-size:12px;outline:none}\nbody.hf-p7 .p7-sort{max-width:122px;color:#f5e3ff;background:#261440;border:1px solid #9c5bc7;border-radius:9px;font-size:11px}\nbody.hf-p7 .p7-grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:7px;overflow-y:auto;align-content:start;padding:4px;min-height:70px}\nbody.hf-p7 .p7-cell{min-width:0;aspect-ratio:1.02;min-height:56px;position:relative;background:radial-gradient(ellipse at 50% 25%,#48206d,#130f31 75%);border:1px solid #9f59c7;border-radius:11px;color:#fff;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:4px;gap:3px}\nbody.hf-p7 .p7-cell.rare{border-color:#459bff}\nbody.hf-p7 .p7-cell.epic{border-color:#e85cff}\nbody.hf-p7 .p7-cell.gold{border-color:#ffce66}\nbody.hf-p7 .p7-cell.selected{box-shadow:0 0 12px #ffc05c99;border-color:#ffd37d}\nbody.hf-p7 .p7-cell.empty{pointer-events:none;color:#653a80;font-size:24px}\nbody.hf-p7 .p7-symbol{font-size:clamp(19px,3vw,32px);line-height:1;text-shadow:0 0 12px #975cff}\nbody.hf-p7 .p7-caption{max-width:99%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:9px;color:#e8d3f3}\nbody.hf-p7 .p7-count{position:absolute;bottom:2px;right:4px;font-weight:800;font-size:11px;background:#0e0d23ae;padding:1px 4px;border-radius:4px}\nbody.hf-p7 .p7-used{position:absolute;top:2px;left:3px;font-size:10px;color:#ffe099}\nbody.hf-p7 .p7-layout{display:grid;grid-template-columns:1fr 1.25fr 1fr;gap:8px;flex:1;min-height:190px}\nbody.hf-p7 .p7-gearcol{display:flex;flex-direction:column;gap:6px;overflow:auto}\nbody.hf-p7 .p7-gearslot{width:100%;display:flex;align-items:center;gap:6px;min-height:46px;background:#241543;border:1px solid #9258be;border-radius:9px;color:#e9d4f6;padding:5px;text-align:left}\nbody.hf-p7 .p7-gearslot.filled{border-color:#6ecefa}\nbody.hf-p7 .p7-gearslot.selected{border-color:#ffcb78}\nbody.hf-p7 .p7-gicon{width:33px;height:33px;border-radius:7px;border:1px solid #975ad5;display:grid;place-items:center;font-size:20px;flex-shrink:0;background:#140c2e}\nbody.hf-p7 .p7-gtext{display:flex;flex-direction:column;overflow:hidden;gap:2px}\nbody.hf-p7 .p7-gtext strong{font-size:10px;color:#ffda93}\nbody.hf-p7 .p7-gtext small{font-size:9px;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}\nbody.hf-p7 .p7-preview-stage{position:relative;min-height:180px;background:radial-gradient(ellipse at 50% 80%,#51248d99,#150f35 55%,#090d2d 90%);border:1px solid #a262e4;border-radius:13px;overflow:hidden}\nbody.hf-p7 .p7-preview-stage:after{content:\"\";position:absolute;bottom:8%;left:18%;right:18%;height:10%;border:2px solid #be75ff;border-radius:50%;box-shadow:0 0 13px #b85aff;pointer-events:none}\nbody.hf-p7 .p7-preview-stage canvas{width:100%!important;height:100%!important;display:block}\nbody.hf-p7 .p7-preview-label{position:absolute;top:7px;left:0;right:0;color:#ffe7af;text-align:center;font:10px system-ui;pointer-events:none;z-index:1}\nbody.hf-p7 .p7-footer{display:flex;justify-content:space-between;gap:5px;margin-top:7px;padding-top:7px;border-top:1px solid #8f53b6}\nbody.hf-p7 .p7-chip{background:#271641;color:#edd9ff;border-radius:7px;border:1px solid #8149aa;padding:7px;font-size:10px}\nbody.hf-p7 .p7-torch{background:#8b4e36;border:1px solid #ffc97e;color:#fff3dd;border-radius:8px;padding:6px;font:bold 10px system-ui}\n@media(max-height:430px){body.hf-p7 #hf-p5-overlay .hf-p5-panel{height:96vh}body.hf-p7 .p7-gearslot{min-height:37px}body.hf-p7 .p7-gicon{width:26px;height:26px;font-size:16px}body.hf-p7 .p7-grid{grid-template-columns:repeat(7,minmax(0,1fr))}body.hf-p7 .p7-cell{min-height:46px}}\n@media(max-width:760px){body.hf-p7 .p7-grid{grid-template-columns:repeat(4,minmax(0,1fr))}body.hf-p7 .hf-p5-detail{width:33%;min-width:135px}}\n";

import * as THREE from 'three';
import { clone as skeletonClone } from 'three/addons/utils/SkeletonUtils.js';
import { ITEM_DB } from '../systems/inventory.js';
const ICON={weapon:'⚔',armor:'🛡',potion:'◉',misc:'✦'};
const TABS=[['all','✥ TODOS'],['weapon','⚔ ARMAS'],['armor','⛨ ARMADURA'],['potion','◉ CONSUMIBLES'],['misc','✦ MATERIALES']];
const RARITY={steel_sword:'rare',ancient_sword:'epic',dragonbone_sword:'gold',dragonscale_armor:'epic',frost_essence:'rare'};
const make=(tag,cls,text,parent)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;if(parent)parent.appendChild(e);return e;};
const label=id=>ITEM_DB[id]?.name||'Vacío';
export class PremiumInventoryP7 {
 constructor(hud){
  this.hud=hud;this.game=hud.game;this.filter='all';this.sort='name';this.query='';this.selectedSlot=null;
  this.previewRenderer=null;this.previewScene=null;this.previewModelRoot=null;this.previewFrame=0;this._dirty=true;
  this._previewInitialized=false;this.tab='all';
  const style=make('style',null,CSS,document.head);style.id='highfly-p7-inventory-style';
  document.body.classList.add('hf-p7');
 }
 head(title,parent){
  const b=make('div','p7-head',undefined,parent),inv=this.game.inventory;
  make('div','p7-title','✦ '+title,b);
  const facts=make('div','p7-facts',undefined,b);
  make('span',null,'ORO '+inv.gold,facts);
  make('span',null,Array.from(inv.slots.values()).filter(x=>x>0).length+' TIPOS',facts);
 }
 render(tab){
  this.tab=tab;this.hud.list.replaceChildren();this.hud.detail.replaceChildren();
  if(tab==='equipment')this.equipment();else this.bag(tab);
  this.details();
 }
 bag(tab){
  const list=this.hud.list;this.head('MOCHILA',list);
  const row=make('div','p7-filters',undefined,list),allowed=tab==='bag'?TABS.filter(x=>['all','potion','misc'].includes(x[0])):TABS;
  if(!allowed.some(x=>x[0]===this.filter))this.filter='all';
  const buttons=[];
  for(const [id,name] of allowed){
   const b=make('button','p7-filter'+(this.filter===id?' active':''),name,row);
   b.type='button';buttons.push([b,id]);
   b.addEventListener('click',()=>{
    this.filter=id;for(const [btn,key] of buttons)btn.classList.toggle('active',key===id);fill();
   });
  }
  const sr=make('div','p7-searchline',undefined,list);
  const search=make('input','p7-search',undefined,sr);
  search.type='search';search.placeholder='⌕ Buscar objetos';search.value=this.query;
  const sort=make('select','p7-sort',undefined,sr);
  for(const [k,v] of [['name','Nombre'],['value','Valor'],['type','Tipo']]){
   const op=make('option',null,v,sort);op.value=k;
  }sort.value=this.sort;
  const grid=make('div','p7-grid',undefined,list);
  const fill=()=>{
   grid.replaceChildren();const inv=this.game.inventory;
   const items=Array.from(inv.slots.entries()).filter(([id,n])=>n>0&&ITEM_DB[id]&&
    (this.filter==='all'||ITEM_DB[id].type===this.filter)&&
    (!this.query||label(id).toLowerCase().includes(this.query.toLowerCase())));
   items.sort((a,b)=>this.sort==='value'?ITEM_DB[b[0]].value-ITEM_DB[a[0]].value:
    this.sort==='type'?ITEM_DB[a[0]].type.localeCompare(ITEM_DB[b[0]].type):label(a[0]).localeCompare(label(b[0])));
   for(let i=0;i<Math.max(18,Math.ceil(items.length/6)*6);i++){
    if(!items[i]){make('div','p7-cell empty','✧',grid);continue;}
    const [id,n]=items[i],db=ITEM_DB[id];
    const btn=make('button','p7-cell '+(RARITY[id]||'')+(this.hud.selected===id?' selected':''),undefined,grid);
    btn.type='button';btn.title=label(id);
    if(Object.values(inv.equipped).includes(id))make('span','p7-used','◆',btn);
    make('span','p7-symbol',ICON[db.type],btn);
    make('span','p7-caption',db.name,btn);make('span','p7-count','×'+n,btn);
    btn.addEventListener('click',()=>{this.hud.selected=id;this.selectedSlot=null;this.render(this.tab);});
   }
  };
  search.addEventListener('input',()=>{this.query=search.value;fill();});
  sort.addEventListener('change',()=>{this.sort=sort.value;fill();});
  fill();
 }
 equipment(){
  const list=this.hud.list,inv=this.game.inventory;
  this.head('PERSONAJE · EQUIPO',list);
  const layout=make('div','p7-layout',undefined,list),left=make('div','p7-gearcol',undefined,layout);
  const stage=make('div','p7-preview-stage',undefined,layout),right=make('div','p7-gearcol',undefined,layout);
  const slot=(parent,title,key,icon)=>{
   const id=inv.equipped[key]||null;
   const b=make('button','p7-gearslot'+(id?' filled':'')+(this.selectedSlot===key?' selected':''),undefined,parent);
   b.type='button';make('span','p7-gicon',id?ICON[ITEM_DB[id].type]:icon,b);
   const txt=make('span','p7-gtext',undefined,b);
   make('strong',null,title,txt);make('small',null,id?label(id):'VACÍO',txt);
   b.addEventListener('click',()=>{this.selectedSlot=key;this.hud.selected=id;this.render('equipment');});
  };
  slot(left,'CABEZA','head','♙');slot(left,'PECHO','armor','⛨');
  slot(left,'HOMBROS','shoulders','✥');slot(left,'MANOS','gloves','✋');
  slot(left,'MANO PRINCIPAL','weapon','⚔');
  slot(right,'CUELLO','neck','◇');slot(right,'PIERNAS','legs','▥');
  slot(right,'PIES','boots','♧');slot(right,'ANILLOS','rings','◈');
  slot(right,'MANO SECUNDARIA','offhand','⚔');
  make('div','p7-preview-label','CAZADOR HIGHFLY · VISTA 3D',stage);
  if(!this.previewCanvas){this.previewCanvas=make('canvas');this.previewCanvas.setAttribute('aria-label','Modelo equipado del cazador');}
  stage.appendChild(this.previewCanvas);
  const foot=make('div','p7-footer',undefined,list);
  make('span','p7-chip','⚔ ATAQUE '+(inv.weaponDamage()+inv.offhandDamage()),foot);
  make('span','p7-chip','⛨ DEFENSA '+inv.armorValue(),foot);
  const torch=make('button','p7-torch',this.game.player.torchOn?'🔥 APAGAR':'🔥 ANTORCHA',foot);
  torch.type='button';torch.addEventListener('click',()=>{this.game.player.toggleTorch();this.game.saveSys?.save();this.render('equipment');});
  this._dirty=true;
 }
 details(){
  const p=this.hud.detail,inv=this.game.inventory,id=this.hud.selected,db=id?ITEM_DB[id]:null;
  const act=(title,fn,disabled=false)=>{
   const b=make('button',null,title,p);b.type='button';b.disabled=disabled;
   if(disabled)b.style.opacity='.45';
   b.addEventListener('click',()=>{fn();this.game.saveSys?.save();this._dirty=true;this.render(this.tab);});
  };
  if(!db||!inv.has(id)){
   make('h3',null,'✧ TU EQUIPO',p);
   make('p',null,'Principal: '+label(inv.equipped.weapon),p);
   make('p',null,'Secundaria: '+label(inv.equipped.offhand),p);
   make('p',null,'Armadura: '+label(inv.equipped.armor),p);
   make('p',null,'HP '+Math.ceil(this.game.stats.hp)+' · MP '+Math.ceil(this.game.stats.mp),p);
   make('p',null,'Seleccioná un objeto para equipar, desequipar o consumir.',p);
  }else{
   make('h3',null,ICON[db.type]+' '+db.name,p);
   make('p',null,db.desc,p);
   make('p',null,'Cantidad ×'+inv.slots.get(id)+' · Valor '+db.value+' oro',p);
   if(db.damage)make('p',null,'Ataque '+db.damage,p);
   if(db.armor)make('p',null,'Defensa '+db.armor,p);
   if(db.type==='weapon'){
    act('EQUIPAR MANO PRINCIPAL',()=>inv.useOrEquip(id,'weapon'),inv.equipped.weapon===id);
    act('EQUIPAR MANO SECUNDARIA',()=>inv.useOrEquip(id,'offhand'),inv.equipped.offhand===id);
    if(inv.equipped.weapon===id)act('DESEQUIPAR PRINCIPAL',()=>inv.unequip('weapon'));
    if(inv.equipped.offhand===id)act('DESEQUIPAR SECUNDARIA',()=>inv.unequip('offhand'));
   }else if(db.type==='armor'){
    act('EQUIPAR ARMADURA',()=>inv.useOrEquip(id),inv.equipped.armor===id);
    if(inv.equipped.armor===id)act('DESEQUIPAR ARMADURA',()=>inv.unequip('armor'));
   }else if(db.type==='potion')act('USAR POCIÓN',()=>{
    inv.useOrEquip(id);if(!inv.has(id))this.hud.selected=null;
   });
  }
  act(this.game.player.torchOn?'🔥 APAGAR ANTORCHA':'🔥 ENCENDER ANTORCHA',()=>this.game.player.toggleTorch());
 }
 initPreview(){
  if(this.previewReady)return;this.previewReady=true;
  try{
   this.previewScene=new THREE.Scene();
   this.previewScene.add(new THREE.AmbientLight(0xffffff,1.8));
   const key=new THREE.DirectionalLight(0xffe2ab,3);key.position.set(3,5,5);this.previewScene.add(key);
   const rim=new THREE.DirectionalLight(0x9e8dff,2);rim.position.set(-4,3,-2);this.previewScene.add(rim);
   this.previewCam=new THREE.PerspectiveCamera(33,1,0.1,50);
   this.previewCam.position.set(3.3,2.55,6);this.previewCam.lookAt(0,1.06,0);
   this.previewRenderer=new THREE.WebGLRenderer({canvas:this.previewCanvas,alpha:true,antialias:false,powerPreference:'low-power'});
   this.previewRenderer.setPixelRatio(1);this.previewRenderer.setClearColor(0x000000,0);
   this.previewCanvas.addEventListener('webglcontextlost',e=>{e.preventDefault();this.previewRenderer=null;});
  }catch(err){console.warn('[P7] 3D preview disabled',err);this.previewRenderer=null;}
 }
 rebuildPreview(){
  if(!this.previewScene)return;
  if(this.previewModelRoot)this.previewScene.remove(this.previewModelRoot);
  try{
   this.game.player.applyEquipment();
   this.previewModelRoot=skeletonClone(this.game.player.rig.root);
   this.previewModelRoot.visible=true;this.previewModelRoot.rotation.y=0;
   this.previewScene.add(this.previewModelRoot);
   this.previewMixer=new THREE.AnimationMixer(this.previewModelRoot);
   const idle=this.game.player.rig.clips.get('Idle');
   if(idle)this.previewMixer.clipAction(idle).play();
   this._dirty=false;
  }catch(err){console.warn('[P7] Preview rig unavailable',err);this.previewModelRoot=null;}
 }
 update(dt){
  if(this.tab!=='equipment'||this.game.state!=='inventory'||!this.previewCanvas?.isConnected)return;
  this.previewFrame+=dt;if(this.previewFrame<0.08)return;
  const step=Math.min(.15,this.previewFrame);this.previewFrame=0;
  this.initPreview();if(!this.previewRenderer)return;
  if(this._dirty||!this.previewModelRoot)this.rebuildPreview();
  if(!this.previewModelRoot)return;
  this.previewMixer?.update(step);this.previewModelRoot.rotation.y+=step*.16;
  const w=Math.max(140,Math.min(280,Math.round(this.previewCanvas.clientWidth||200))),
        h=Math.max(150,Math.min(310,Math.round(this.previewCanvas.clientHeight||230)));
  if(this._w!==w||this._h!==h){
   this._w=w;this._h=h;this.previewRenderer.setSize(w,h,false);
   this.previewCam.aspect=w/h;this.previewCam.updateProjectionMatrix();
  }
  try{this.previewRenderer.render(this.previewScene,this.previewCam);}
  catch(err){console.warn('[P7] Preview draw disabled',err);this.previewRenderer=null;}
 }
}
